begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions,pg_temp;
select no_plan();
insert into auth.users(id) values(md5('complete_a')::uuid),(md5('complete_b')::uuid);
insert into profiles(id,display_name) values(md5('complete_a')::uuid,'A'),(md5('complete_b')::uuid,'B');
insert into account_preferences(owner_id) values(md5('complete_a')::uuid),(md5('complete_b')::uuid);
set local role authenticated;
select set_config('request.jwt.claims',json_build_object('sub',md5('complete_a')::uuid,'role','authenticated')::text,true);
select set_config('body_test.w',start_ad_hoc_workout()::text,true);
select is((select count(*)::int from workout_training_summary(array[current_setting('body_test.w')::uuid])),0,'active session has no completed summary');
insert into workout_movements(owner_id,workout_session_id,position,suggested_pattern_id,suggested_muscle_id,suggested_type,suggested_title,movement_nonce)
select auth.uid(),current_setting('body_test.w')::uuid,i,(select id from movement_patterns where slug='horizontal_push'),(select id from muscle_groups where slug='pectorals'),'compound','Press '||i,md5('complete_m_nonce'||i)::uuid from generate_series(1,2)i;
select set_config('body_test.e1',select_program_exercise((select id from workout_movements where movement_nonce=md5('complete_m_nonce1')::uuid),(select id from exercises where slug='barbell_bench_press'),null,md5('complete_e1')::uuid)::text,true);
select set_config('body_test.e2',select_program_exercise((select id from workout_movements where movement_nonce=md5('complete_m_nonce2')::uuid),(select id from exercises where slug='barbell_bench_press'),null,md5('complete_e2')::uuid)::text,true);
create function pg_temp.record_set(item uuid,pos int,reps int,kind text default 'working') returns void language plpgsql security invoker as $$
declare z public.workout_sets;
begin select * into z from public.workout_sets where workout_exercise_id=item and owner_id=auth.uid() and position=pos;perform public.log_workout_set(p_item=>item,p_id=>z.id,p_operation=>'save',p_revision=>z.revision,p_mutation=>gen_random_uuid(),p_reps=>reps,p_weight=>50,p_type=>kind,p_completed=>true);end $$;
select pg_temp.record_set(current_setting('body_test.e1')::uuid,1,8);
select pg_temp.record_set(current_setting('body_test.e1')::uuid,2,8,'warm_up');
select pg_temp.record_set(current_setting('body_test.e1')::uuid,3,0);
select pg_temp.record_set(current_setting('body_test.e2')::uuid,1,8);
select pg_temp.record_set(current_setting('body_test.e2')::uuid,2,8);
select log_workout_set(p_item=>current_setting('body_test.e2')::uuid,p_id=>(select id from workout_sets where workout_exercise_id=current_setting('body_test.e2')::uuid and position=2),p_operation=>'remove',p_revision=>1,p_mutation=>gen_random_uuid());
select end_workout(current_setting('body_test.w')::uuid,'completed');
select is((select working_sets::int from workout_training_summary(array[current_setting('body_test.w')::uuid])),2,'working summary excludes warm-up, zero reps, deleted and unconfirmed pending work');
select is((select exercises_performed::int from workout_training_summary(array[current_setting('body_test.w')::uuid])),2,'distinct actual selections count independently even when canonical exercise is repeated');
select is((select working_sets::int from workout_history() where id=current_setting('body_test.w')::uuid),2,'history shares qualifying working-set authority');
select is((select warm_up_sets::int from workout_history() where id=current_setting('body_test.w')::uuid),1,'warm-up count remains separate');
select is((select count(*)::int from workout_training_summary(array[current_setting('body_test.w')::uuid,current_setting('body_test.w')::uuid])),1,'duplicate requested IDs do not duplicate summary');
select is(end_workout(current_setting('body_test.w')::uuid,'completed'),current_setting('body_test.w')::uuid,'repeated closure returns original session');
select is((select count(*)::int from workout_sessions),1,'repeated reads/closure create no session or event');
select set_config('body_test.empty',start_ad_hoc_workout()::text,true);select end_workout(current_setting('body_test.empty')::uuid,'completed');
select is((select working_sets::int from workout_training_summary(array[current_setting('body_test.empty')::uuid])),0,'empty completion has honest zero training');
select is((select exercises_performed::int from workout_training_summary(array[current_setting('body_test.empty')::uuid])),0,'unselected/empty slots are not performed exercises');
select set_config('body_test.abandoned',start_ad_hoc_workout()::text,true);select end_workout(current_setting('body_test.abandoned')::uuid,'abandoned');
select is((select count(*)::int from workout_training_summary(array[current_setting('body_test.abandoned')::uuid])),0,'abandoned sessions never produce completion summary');
select throws_ok($$select * from workout_training_summary(null)$$,'22023',null,'null session window rejected');
select throws_ok($$select * from workout_training_summary(array[null]::uuid[])$$,'22023',null,'null identity rejected');
select throws_ok($$select * from workout_training_summary(array(select gen_random_uuid() from generate_series(1,52)))$$,'22023',null,'summary work is bounded');
select is((select count(*)::int from workout_training_summary(array[]::uuid[])),0,'empty batch is safe');
select throws_ok($$delete from workout_sessions where id=current_setting('body_test.w')::uuid$$,'23514',null,'completion cannot erase historical session without retention authority');
select set_config('request.jwt.claims',json_build_object('sub',md5('complete_b')::uuid,'role','authenticated')::text,true);
select is((select count(*)::int from workout_training_summary(array[current_setting('body_test.w')::uuid])),0,'foreign IDs reveal no completed facts');
reset role;
-- Authorized correction fixture: derived statistics follow actual eligible evidence, not stored counters.
update workout_sets set deleted_at=clock_timestamp() where workout_exercise_id=current_setting('body_test.e2')::uuid and position=1;
set local role authenticated;
select set_config('request.jwt.claims',json_build_object('sub',md5('complete_a')::uuid,'role','authenticated')::text,true);
select is((select working_sets::int from workout_training_summary(array[current_setting('body_test.w')::uuid])),1,'corrected evidence recalculates without manufacturing work');
select is((select exercises_performed::int from workout_training_summary(array[current_setting('body_test.w')::uuid])),1,'selections without remaining qualifying work stop counting');
select is((select working_sets::int from workout_history() where id=current_setting('body_test.w')::uuid),1,'corrected history and completion remain consistent');
reset role;set local role anon;
select throws_ok($$select * from workout_training_summary(array[]::uuid[])$$,'42501',null,'anonymous completion data denied');
reset role;set local role service_role;
select throws_ok($$select * from workout_training_summary(array[]::uuid[])$$,'42501',null,'service role not exposed');
reset role;select * from finish();rollback;
